(function(){
'use strict';
const originalFetch=window.fetch.bind(window);
const RULES=`אריאלה מנהלת שיחה טבעית כמו סוכנת נסיעות ולא שאלון. אין להציג קודים פנימיים, true/false או enum, ואין לשאול שוב מידע שכבר נמסר.
בחופשה רגילה: קודם אוספים יעד או בקשה שאריאלה תבחר, מועד, ומי נוסע. אחר כך ורק אחר כך אוספים את כל פרטי הטיסה: תקציב, כבודה, וישיר או קונקשן. אם פרט כבר נמסר לא שואלים אותו שוב. רק לאחר שכל פרטי הטיסה נאספו שואלים אם הלקוח רוצה שאריאלה תבנה את הטיול כולו או רק עזרה בדברים מסוימים. אין להציג לינה/רכב/אטרקציות/תכנון מסלול לפני השלמת פרטי הטיסה.
אם אריאלה בונה את הטיול: קודם תחומי עניין, אחר כך מסלול הגיוני, אחר כך לינה לפי המסלול, ורק אז רכב וימי/מקומות איסוף והחזרה. אם הלקוח רוצה עזרה נקודתית, ממשיכים רק לשירותים שביקש. ברכב משתמשים אוטומטית במספר הנוסעים ובכבודה שכבר ידועים כדי לסנן רכב קטן מדי.
תאריכים: תאריך מדויק נשמר; חודש פירושו כל החודש; סופ״ש = יציאה רביעי/חמישי וחזרה שבת/ראשון; שבוע = ראשון עד חמישי; תקופה כמו סוף אוקטובר נשמרת כתקופה. אין לשאול אוטומטית על גמישות או משך.
בסיום שאלי אם יש עוד משהו חשוב לפני החיפוש.
הביטויים "חופשה חדשה", "מהתחלה", "נתחיל מחדש" וביטויים ברורים מקבילים פותחים חופשה חדשה. מנקים את נתוני החופשה הפעילה בלבד; פרטי המשתמש והחופשות הקודמות נשמרים.`;
function isChat(input,init){const u=typeof input==='string'?input:(input&&input.url)||'';return /\/api\/ariella\/chat(?:\?|$)/.test(u)&&String((init&&init.method)||'GET').toUpperCase()==='POST';}
window.fetch=async function(input,init){if(isChat(input,init)&&init&&typeof init.body==='string'){try{const p=JSON.parse(init.body),m=String(p.message||'').trim();if(m){p.message=['הודעת הלקוח המקורית:',m,'',RULES].join('\n');init=Object.assign({},init,{body:JSON.stringify(p)});}}catch(e){}}return originalFetch(input,init);};
function isNew(text){return /^(?:מהתחלה|חופשה חדשה|נתחיל מחדש|להתחיל מחדש|בואי נתחיל מחדש|בואי נחפש משהו אחר)\s*[.!?]*$/i.test(String(text||'').trim());}
function flightComplete(){return ['destination','dates','travelers','budget','flight','baggage'].every(k=>document.querySelector(`#ariellaDesktopChat [data-summary-key="${k}"].is-filled`));}
function resetVacation(){try{['ariellaChatState:v3','ariellaChatState:v4'].forEach(k=>{localStorage.removeItem(k);sessionStorage.removeItem(k);});}catch(e){}document.querySelectorAll('#ariellaDesktopChat .ac-detail').forEach(r=>{r.classList.remove('is-filled');const s=r.querySelector('span');if(s)s.textContent=document.documentElement.lang==='en'?'Not specified yet':'עדיין לא צוין';});}
function hideLegacyGate(){document.querySelectorAll('#vacationTypeGate,.vacation-type-gate,.vacation-type-grid').forEach(x=>x.style.setProperty('display','none','important'));}
function ensureDirectChatShell(){
  const params=new URLSearchParams(location.search);if(params.get('ariella_chat')!=='1')return null;
  const wizard=document.getElementById('tripWizard');if(!wizard)return null;
  let chat=document.getElementById('ariellaDesktopChat');if(chat)return chat;
  const isEn=document.documentElement.lang==='en';
  const style=document.createElement('style');style.id='ariella-direct-chat-shell-style';style.textContent=`body.ariella-chat-preview-active #tripWizard{display:none!important}body.ariella-chat-preview-active .trip-back-bar{display:none!important}#ariellaDesktopChat{width:min(1280px,92%);margin:18px auto 40px;direction:${isEn?'ltr':'rtl'};font-family:Arial,"Segoe UI",sans-serif}#ariellaDesktopChat .ac-shell{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,.85fr);gap:22px;align-items:stretch}#ariellaDesktopChat .ac-chat,#ariellaDesktopChat .ac-summary{background:#fffaf2;border:1px solid rgba(201,154,63,.38);border-radius:22px;box-shadow:0 14px 38px rgba(23,40,63,.08);overflow:hidden}#ariellaDesktopChat .ac-chat{height:min(650px,calc(100vh - 150px));min-height:520px;display:flex;flex-direction:column}.ac-head{display:flex;align-items:center;gap:14px;padding:20px 24px;background:linear-gradient(135deg,#102b30,#18373a);color:#fff;border-bottom:1px solid #c99a3f}.ac-avatar{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;flex:0 0 auto;background:linear-gradient(145deg,#f6d98b,#c99a3f);border:2px solid #fff3cf;color:#17283f;font:700 28px Georgia,serif}.ac-head-copy strong{display:block;font-size:21px}.ac-online{margin-inline-start:auto;color:#d8e7e5;font-size:13px}.ac-messages{flex:1;min-height:0;padding:28px 30px;display:flex;flex-direction:column;gap:14px;background:linear-gradient(180deg,#fffdf8,#fbf5e9);overflow-y:auto}.ac-compose{padding:17px 20px;border-top:1px solid #eadfc8;background:#fff;display:flex;gap:10px;align-items:center}.ac-compose textarea{flex:1;min-height:52px;max-height:125px;resize:none;border:1px solid #d9cdb8;border-radius:14px;padding:14px 15px;font:inherit;background:#fffdf9;color:#17283f}.ac-send{height:52px;min-width:92px;border:0;border-radius:13px;background:#0b8f9c;color:#fff;font-weight:800;font-size:15px}.ac-summary{padding:0 22px 22px;align-self:start}.ac-summary-head{margin:0 -22px 18px;padding:20px 22px 16px;border-bottom:1px solid #eadfc8}.ac-summary-head strong{display:block;font-size:22px;color:#17283f}.ac-summary-head small{display:block;margin-top:5px;color:#75808b}.ac-detail{display:grid;grid-template-columns:34px 1fr;gap:10px;padding:11px 0;border-bottom:1px solid #eee5d5}.ac-detail b{display:block;color:#17283f;font-size:14px}.ac-detail span{display:block;color:#8a8173;font-size:14px}@media(max-width:899px){#ariellaDesktopChat{width:100%;margin:0 auto 24px;padding:8px 10px}#ariellaDesktopChat .ac-shell{display:flex;flex-direction:column;gap:12px}#ariellaDesktopChat .ac-chat{height:calc(100dvh - 125px);min-height:500px;border-radius:16px}#ariellaDesktopChat .ac-head{padding:10px 12px}.ac-online{display:none}.ac-messages{padding:18px 12px}.ac-compose{padding:10px}.ac-compose textarea{min-height:48px}.ac-send{height:48px;min-width:68px}.ac-summary{border-radius:16px}}`;
  document.head.appendChild(style);
  const defs=[['destination','🌍',isEn?'Destination':'יעד'],['dates','📅',isEn?'Dates':'תאריכים'],['travelers','👥',isEn?'Travelers':'נוסעים'],['budget','💰',isEn?'Budget':'תקציב'],['flight','✈️',isEn?'Flight':'טיסה'],['baggage','🧳',isEn?'Baggage':'כבודה']];
  chat=document.createElement('section');chat.id='ariellaDesktopChat';chat.innerHTML=`<div class="ac-shell"><div class="ac-chat"><div class="ac-head"><div class="ac-avatar">A</div><div class="ac-head-copy"><strong>${isEn?'Ariella — your personal travel agent':'אריאלה — סוכנת הנסיעות האישית שלך'}</strong></div><div class="ac-online">${isEn?'Available':'זמינה עכשיו'}</div></div><div class="ac-messages" id="ariellaChatMessages"></div><div class="ac-compose"><textarea id="ariellaChatInput" rows="1"></textarea><button type="button" class="ac-send" id="ariellaChatSend">${isEn?'Send':'שליחה'}</button></div></div><aside class="ac-summary"><div class="ac-summary-head"><strong>${isEn?'My vacation':'החופשה שלי'}</strong><small>${isEn?'The details Ariella understands from the conversation will appear here.':'הפרטים שאריאלה תבין מהשיחה יתעדכנו כאן.'}</small></div>${defs.map(d=>`<div class="ac-detail" data-summary-key="${d[0]}"><div>${d[1]}</div><div><b>${d[2]}</b><span>${isEn?'Not specified yet':'עדיין לא צוין'}</span></div></div>`).join('')}</aside></div>`;
  wizard.parentNode.insertBefore(chat,wizard);document.body.classList.add('ariella-chat-preview-active');hideLegacyGate();
  const existing=[...document.scripts].find(s=>/ariella-chat-confirmation-20260911\.js/.test(s.src));
  if(existing){const reload=document.createElement('script');reload.src=existing.src.split('?')[0]+'?v=20260914-direct2';document.body.appendChild(reload);}
  return chat;
}
function tidy(){hideLegacyGate();const c=document.getElementById('ariellaDesktopChat');if(!c)return;c.querySelectorAll('.ariella-new-chat').forEach(x=>x.remove());c.querySelectorAll('.ac-flow-card').forEach(x=>{if(!flightComplete())x.remove();});}
function boot(){document.body.classList.add('ariella-chat-preview-active');ensureDirectChatShell();const st=document.createElement('style');st.textContent=`#vacationTypeGate,.vacation-type-gate,.vacation-type-grid{display:none!important}#ariellaDesktopChat .ariella-new-chat{display:none!important}@media(max-width:899px){#ariellaDesktopChat .ac-head{min-height:64px!important;padding:8px 12px!important;gap:9px!important;flex-wrap:nowrap!important}#ariellaDesktopChat .ac-avatar{width:44px!important;height:44px!important;flex:0 0 44px!important}#ariellaDesktopChat .ac-head-copy{min-width:0!important;flex:1!important}#ariellaDesktopChat .ac-head-copy strong{font-size:14px!important;line-height:1.2!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}#ariellaDesktopChat .ac-online{display:none!important}}`;document.head.appendChild(st);tidy();const c=document.getElementById('ariellaDesktopChat'),send=c?.querySelector('#ariellaChatSend'),inp=c?.querySelector('#ariellaChatInput');if(send&&inp){send.addEventListener('click',()=>{if(isNew(inp.value))resetVacation();},true);inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&isNew(inp.value))resetVacation();},true);}new MutationObserver(tidy).observe(document.body,{childList:true,subtree:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
